package org.apache.commons.math.ode.nonstiff;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathIllegalArgumentException;
import org.apache.commons.math.exception.MathIllegalStateException;
import org.apache.commons.math.ode.ExpandableStatefulODE;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.exception.MathIllegalStateException;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.Mockito.*;

/**
 * Unit tests for EmbeddedRungeKuttaIntegrator.integrate
 */
public class EmbeddedRungeKuttaIntegrator_integrate_TriageGen0Test {

    private TestIntegrator integrator;
    private ExpandableStatefulODE mockEquations;

    // Mock implementation of the abstract class to test the integrate method
    private static class TestIntegrator extends EmbeddedRungeKuttaIntegrator {
        private double errorToReturn = 0.5;
        private int computeDerivativesCalls = 0;

        protected TestIntegrator() {
            super("test", true, 
                  new double[]{0, 0.5, 1.0}, 
                  new double[][]{{0, 0}, {0.5, 0}, {0, 0}}, 
                  new double[]{0, 0.5, 1.0}, 
                  mock(RungeKuttaStepInterpolator.class), 
                  1e-10, 1.0, 1e-6, 1e-6);
        }

        @Override
        public int getOrder() { return 2; }

        @Override
        protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
            return errorToReturn;
        }

        @Override
        protected void computeDerivatives(double t, double[] y, double[] yDot) {
            computeDerivativesCalls++;
            for (int i = 0; i < y.length; i++) {
                yDot[i] = y[i]; // Simple dy/dt = y
            }
        }

        // Helper to control error for testing branch coverage (error >= 1.0)
        public void setErrorToReturn(double error) {
            this.errorToReturn = error;
        }

        public int getComputeDerivativesCalls() {
            return computeDerivativesCalls;
        }
    }

    // Mocking the interpolator requirements
    private static RungeKuttaStepInterpolator prototype;

    @Before
    public void setUp() {
        prototype = mock(RungeKuttaStepInterpolator.class);
        when(prototype.copy()).thenReturn(mock(RungeKuttaStepInterpolator.class));

        integrator = new TestIntegrator();
        mockEquations = mock(ExpandableStatefulODE.class);

        // Default mock behavior
        when(mockEquations.getCompleteState()).thenReturn(new double[]{1.0});
        when(mockEquations.getTime()).thenReturn(0.0);
        when(mockEquations.getPrimaryMapper()).thenReturn(null);
        when(mockEquations.getSecondaryMappers()).thenReturn(null);
    }

    @Test
    public void testIntegrate_ForwardSuccess() {
        // Test a simple forward integration where error is always < 1.0
        integrator.setErrorToReturn(0.5);
        double targetTime = 0.5;

        integrator.integrate(mockEquations, targetTime);

        verify(mockEquations).setTime(anyDouble());
        verify(mockEquations).setCompleteState(any(double[].class));
    }

    @Test
    public void testIntegrate_Backward() {
        // Test backward integration (t < equations.getTime())
        when(mockEquations.getTime()).thenReturn(1.0);
        when(mockEquations.getCompleteState()).thenReturn(new double[]{1.0});

        integrator.setErrorToReturn(0.1);
        integrator.integrate(mockEquations, 0.5);

        verify(mockEquations).setTime(argThat(t -> t <= 0.5));
    }

    @Test
    public void testIntegrate_RejectStep() {
        // Test the while(error >= 1.0) loop for step rejection
        // First call returns 2.0 (reject), second call returns 0.5 (accept)
        integrator.setErrorToReturn(2.0);

        // We need to simulate the error changing inside the loop.
        // Since we can't easily change it mid-call in a simple mock, 
        // we use a custom implementation in the test class if needed, 
        // but here we'll simulate the logic by making the integrator 
        // hit the error condition.

        // To trigger the 'while (error >= 1.0)' loop, we use a custom integrator
        TestIntegrator errorIntegrator = new TestIntegrator() {
            private int count = 0;
            @Override
            protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) {
                count++;
                return (count == 1) ? 2.0 : 0.5;
            }
        };

        errorIntegrator.integrate(mockEquations, 0.5);
        // If it reaches here without infinite loop, the rejection logic worked
        verify(mockEquations, atLeastOnce()).setCompleteState(any());
    }

    @Test(expected = MathIllegalArgumentException.class)
    public void testIntegrate_InvalidArguments() {
        // Trigger sanityChecks (usually checks if t < minStep or similar)
        // Since we don't have the source of sanityChecks, we assume 
        // passing null or invalid state triggers it.
        integrator.integrate(null, 1.0);
    }

    @Test
    public void testIntegrate_FsalTrue() {
        // Test with fsal = true (the constructor in setUp sets it to true)
        integrator.setErrorToReturn(0.1);
        integrator.integrate(mockEquations, 0.2);

        // With fsal, computeDerivatives should be called fewer times 
        // because the last yDot is reused.
        assertTrue(integrator.getComputeDerivativesCalls() > 0);
    }

    @Test
    public void testIntegrate_VectorTolerance() {
        // Test the branch where vecAbsoluteTolerance is not null
        double[] absTol = {1e-6, 1e-6};
        double[] relTol = {1e-6, 1e-6};

        // We need to instantiate a new integrator with vector tolerances
        // This requires accessing the protected constructor via a subclass
        EmbeddedRungeKuttaIntegrator vecIntegrator = new EmbeddedRungeKuttaIntegrator(
                "vecTest", true, new double[]{0, 1}, new double[][]{{0}, {0}}, new double[]{1, 1}, 
                prototype, 1e-10, 1.0, absTol, relTol) {
            @Override public int getOrder() { return 1; }
            @Override protected double estimateError(double[][] yDotK, double[] y0, double[] y1, double h) { return 0.1; }
            @Override protected void computeDerivatives(double t, double[] y, double[] yDot) { yDot[0] = 1; }
        };

        ExpandableStatefulODE vecEq = mock(ExpandableStatefulODE.class);
        when(vecEq.getCompleteState()).thenReturn(new double[]{1.0, 1.0});
        when(vecEq.getTime()).thenReturn(0.0);
        when(vecEq.getPrimaryMapper()).thenReturn(null);
        when(vecEq.getSecondaryMappers()).thenReturn(null);

        vecIntegrator.integrate(vecEq, 0.5);
        verify(vecEq).setCompleteState(any());
    }
}
